package com.meterflow.notifications;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="webhook_deliveries")public class WebhookDelivery{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(nullable=false)private UUID webhookId;@Column(nullable=false)private String eventType;@Column(nullable=false,length=4000)private String payload;@Column(nullable=false)private String status="PENDING";@Column(nullable=false)private int attempts=0;@Column(length=1000)private String lastResponse="";@Column private Instant nextAttemptAt=Instant.now();@Column(nullable=false)private Instant createdAt=Instant.now();protected WebhookDelivery(){}public WebhookDelivery(UUID w,String e,String p){webhookId=w;eventType=e;payload=p;}public UUID getId(){return id;}public UUID getWebhookId(){return webhookId;}public String getEventType(){return eventType;}public String getPayload(){return payload;}public String getStatus(){return status;}public int getAttempts(){return attempts;}public String getLastResponse(){return lastResponse;}public Instant getNextAttemptAt(){return nextAttemptAt;}public void success(String s){attempts++;status="DELIVERED";lastResponse=s;nextAttemptAt=null;}public void failure(String s){attempts++;lastResponse=s;if(attempts>=5){status="FAILED";nextAttemptAt=null;}else{status="PENDING";nextAttemptAt=Instant.now().plusSeconds((long)Math.pow(2,attempts)*30);}}public void replay(){if("PENDING".equals(status))return;status="PENDING";attempts=0;nextAttemptAt=Instant.now();}}
